import{z as l,x as s,o as t,c as B,q as e,j as o,D as E,d as n,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"130/30","description":"","frontmatter":{"title":"130/30","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/one-thirty-thirty.md","filePath":"quant/one-thirty-thirty.md","lastUpdated":1791063341000}'),d={name:"quant/one-thirty-thirty.md"};function p(h,a,_,m,u,c){const r=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=e('<h1 id="_130-30" tabindex="-1">130/30 <a class="header-anchor" href="#_130-30" aria-label="Permalink to &quot;130/30&quot;">​</a></h1><div class="epigraph"><p>130/30 用有限卖空把多头主动权重的对称性补上：看好的可以超配到超过权重上限，资金来自看空的 30%。</p><footer>—— Jacobs, Levy and Starer, On the Optimality of Long–Short Strategies, Financial Analysts Journal, 1998 前后对放松多头约束的讨论</footer></div><p><a href="/quant/long-short-equity">上一课</a>是双侧都可以到 100% 的中性或多空。130/30 的缺口是<strong>多头基准产品</strong>：净暴露保持约 100%，总暴露 160%，空头通常 30%。主干 <a href="/quant/portfolio-constraints">组合约束</a> 已写多头-only 的约束成本。本课写放松 30% 卖空值不值借券与跟踪误差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯多头主动：低配一只股票最多到权重 0，超配受集中度限制。信息在看空一侧被截断。允许 30% 卖空，把释放的资金加到多头，形成 130 多 / 30 空，净仍约 1。问题是：这 30% 的借券与主动风险，是否提高 IR 足以覆盖成本。若空头只是把多头约束「对称化」且信号在两侧同样有效，Jacobs–Levy 的逻辑说应当提高效率；若信号主要在多头流动性名字、空头都是借券贵的小盘，130/30 会毁价值。</p><p><span class="marginnote">术语翻译：130/30 就是「每 100 元净值，买 130 元最看好的、卖空 30 元最看不上的」——多买的那 30 元恰好来自卖空收到的 30 元，所以净敞口仍是 100 元，市场涨跌的暴露与普通指数基金相同。</span></p>',6)),(t(),o(i,null,{default:E(()=>[A(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%94%BE%E6%9D%BE%2030%25%20%E5%8D%96%E7%A9%BA%E5%80%BC%E4%B8%8D%E5%80%BC%3F%22%7D%20--%3E%20S%7B%22%E4%BF%A1%E5%8F%B7%E5%9C%A8%E7%9C%8B%E7%A9%BA%E4%BE%A7%E5%90%8C%E6%A0%B7%E6%9C%89%E6%95%88%3F%22%7D%0A%20%20Q%20--%3E%20L%7B%22%E5%80%9F%E5%88%B8%E5%8F%AF%E5%BE%97%E4%B8%94%E4%BE%BF%E5%AE%9C%3F%22%7D%0A%20%20S%20--%3E%7C%22%E6%98%AF%22%7C%20A%5B%22%E7%A9%BA%E8%85%BF%E5%AF%B9%E7%A7%B0%E5%8C%96%20IR%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20S%20--%3E%7C%22%E5%90%A6%22%7C%20B%5B%22%E7%A9%BA%E8%85%BF%E5%8F%AA%E5%89%A9%E5%99%AA%E9%9F%B3%20%E6%88%90%E6%9C%AC%E7%BA%AF%E4%BA%8F%22%5D%0A%20%20L%20--%3E%7C%22%E6%98%AF%22%7C%20A%0A%20%20L%20--%3E%7C%22%E5%90%A6%22%7C%20C%5B%22%E7%A9%BA%E5%A4%B4%E5%A0%86%E5%9C%A8%E5%B0%91%E6%95%B0%E5%8F%AF%E5%80%9F%E5%90%8D%20%E9%9B%86%E4%B8%AD%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>与市场中性：130/30 保留几乎全部市场 beta，基准是指数，跟踪误差有限。客户买的是「增强指数」而不是绝对收益。评价应用超额与 TE，不是用中性基金的夏普。</p><h3 id="_30-不是魔术数字" tabindex="-1">30 不是魔术数字 <a class="header-anchor" href="#_30-不是魔术数字" aria-label="Permalink to &quot;30 不是魔术数字&quot;">​</a></h3><p>140/40、120/20 是同一族。最优空头比例取决于借券供给、基准集中度与信号双边性。固定 30 是产品营销与风险预算的折中。优化里应把空头比例当约束参数做稳健，而不是当理论最优。</p><p><span class="marginnote">130/30 的杠杆是总暴露 1.6，不是 1.3 倍净值的融资杠杆 ETF。重置与拖累不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在基准权重附近优化主动 \\(w-w_b\\)，约束 \\(\\sum w=1\\)、\\(\\sum w^-=0.3\\)、\\(w_i\\ge -c\\)。风险用相对 \\(\\Sigma\\)。借券成本进预期收益。对照：纯多头增强 vs 130/30 的扣费 IR/TE。执行：空头名单预审。</p><p><span class="marginnote">数字实例：卖空 30% 的组合、平均借券费 0.5%/年，成本约 0.15%/年（30%×0.5%）；若空腿信号每年只多贡献 0.1% 超额，130/30 扣完借券费反而不如纯多头增强。所以借券成本必须先进预期收益、再算 IR，而不是事后补记。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多头-only 的有效前沿被截断。放松卖空把一部分截断补回，主动风险的每单位 IR 上升——若短腿可执行。不可执行时，优化器会把空头堆在少数可借名字，变成集中空头风险，效率下降。</p>',9)),(t(),o(i,null,{default:E(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Long%5B%22%E7%BA%AF%E5%A4%9A%E5%A4%B4%20%E4%BD%8E%E9%85%8D%E6%88%AA%E6%96%AD%E5%9C%A8%200%22%5D%20--%3E%20Rel%5B%22%E7%9B%B8%E5%AF%B9%E5%9F%BA%E5%87%86%E4%BC%98%E5%8C%96%22%5D%0A%20%20Short30%5B%22%E5%85%81%E8%AE%B8%2030%25%20%E7%A9%BA%22%5D%20--%3E%20Rel%0A%20%20Rel%20--%3E%20Prod%5B%22%E5%87%80%E7%BA%A6%20100%25%20%E6%80%BB%20160%25%22%5D%0A%20%20Loan%5B%22%E5%80%9F%E5%88%B8%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20Feas%5B%22%E7%9F%AD%E8%85%BF%E6%98%AF%E5%90%A6%E7%9C%9F%E8%83%BD%E5%AF%B9%E7%A7%B0%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2008 年式的做空限制会瞬间把 130/30 变回残缺多头。基准若是不可做空的指数（部分 A 股），产品结构要改，见中国课。费用高于指数增强，后课费用复合要单独算。</p><p><span class="marginnote">常见误区：初学者容易把 130/30 当成「1.3 倍杠杆基金」。实际上净暴露仍是 1：卖空所得现金即时买入多头，1.6 只是总名义敞口；融资结构、每日重置方式都与杠杆 ETF 完全不同，拖累机制也不可类比。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>130/30 是带有限卖空的增强指数，不是市场中性。</li><li>价值取决于信号双边性与借券；30% 是产品参数。</li><li>评价用 TE 与超额，不用绝对夏普。</li><li>出处：Jacobs, Levy and Starer 对多空相对多头约束的讨论，<em>FAJ</em>。</li></ul>',5))])}const D=l(d,[["render",p]]);export{C as __pageData,D as default};
